#!/usr/bin/env bash
if [ "${1:-}" = "-i" ]; then shift
  if /usr/bin/sed --version >/dev/null 2>&1; then exec /usr/bin/sed -i "$@"
  else exec /usr/bin/sed -i '' "$@"; fi
fi
exec /usr/bin/sed "$@"
''');
