    echo \$((race_left-1)) > "\$FA_RACE_FILE"
    "\$FA_REAL_GIT" -C "\$FA_RACER" -c user.email=t@t -c user.name=t commit -q --allow-empty -m "raced commit"
    "\$FA_REAL_GIT" -C "\$FA_RACER" push -q origin main
