int writeIpa(Directory sandbox, {required bool withSymbols}) {
  final archive = Archive();
  void add(String name, String content) =>
      archive.addFile(ArchiveFile.bytes(name, utf8.encode(content)));
  add('Payload/Fa.app/Info.plist', '<?xml version="1.0"?><plist/>');
  add('Payload/Fa.app/Fa', 'fake-mach-o');
  add('Payload/Fa.app/_CodeSignature/CodeResources', 'sig-resources');
  if (withSymbols) {
    add('Symbols/fa.app.dSYM/Contents/Info.plist', 'dsym-plist');
    add('Symbols/fa.app.dSYM/Contents/Resources/DWARF/Fa', 'dwarf' * 4096);
  }
  final bytes = ZipEncoder().encode(archive);
  final dir = Directory('${sandbox.path}/flutter_app/build/ios/ipa')
    ..createSync(recursive: true);
  File('${dir.path}/fa.ipa').writeAsBytesSync(bytes);
  return bytes.length;
}

