#!/usr/bin/env bash
if [ "${1:-}" = "-f%z" ]; then
  /usr/bin/stat -c%s "$2" 2>/dev/null || /usr/bin/stat -f%z "$2"
else
  exec /usr/bin/stat "$@"
fi
