{"newText":"    test('.gitignore sweeps future cov-*/ scratch dirs', () {
      expect(
        read('.gitignore').split('\n').map((line) => line.trim()),
        contains('cov-*/'),
        reason:
            'next to the coverage/ entries: a stray cov-* run dir '
            'must never become committable again',
      );
