{"newText":"/// Fixture IPA (a real zip with the export shape: Payload/ plus, when
/// [withSymbols], the debug-symbols dir the strip step repacks away),
/// written to the sandbox path `find flutter_app/build/ios` discovers.
/// The DWARF payload is RANDOM bytes (the real dSYM bulk is machine code
/// — incompressible), so "IPA stripped: BEFORE -> AFTER" must shrink the
/// file — a no-op strip cannot pass on this fixture.
int writeIpa(Directory sandbox, {required bool withSymbols}) {
  final rng = Random(1403);
  final dwarf = List<int>.generate(256 * 1024, (_) => rng.nextInt(256));
  final archive = Archive();
  void add(String name, List<int> bytes) =>
      archive.addFile(ArchiveFile.bytes(name, bytes));
  add('Payload/Fa.app/Info.plist', utf8.encode('<?xml version="1.0"?><plist/>'));
  add('Payload/Fa.app/Fa', utf8.encode('fake-mach-o'));
  add('Payload/Fa.app/_CodeSignature/CodeResources',
      utf8.encode('sig-resources'));
  if (withSymbols) {
    add('Symbols/fa.app.dSYM/Contents/Info.plist', utf8.encode('dsym-plist'));
    add('Symbols/fa.app.dSYM/Contents/Resources/DWARF/Fa', dwarf);
  }","oldText":"/// Fixture IPA (a real zip with the export shape: Payload/ plus, when
/// [withSymbols], the debug-symbols dir the strip step repacks away),
/// written to the sandbox path `find flutter_app/build/ios` discovers.
int writeIpa(Directory sandbox, {required bool withSymbols}) {
  final archive = Archive();
  void add(String name, String content) =>
      archive.addFile(ArchiveFile.bytes(name, utf8.encode(content)));
  add('Payload/Fa.app/Info.plist', '<?xml version="1.0"?><plist/>');
  add('Payload/Fa.app/Fa', 'fake-mach-o');
  add('Payload/Fa.app/_CodeSignature/CodeResources', 'sig-resources');
  if (withSymbols) {
    add('Symbols/fa.app.dSYM/Contents/Info.plist', 'dsym-plist');
    add('Symbols/fa.app.dSYM/Contents/Resources/DWARF/Fa', 'dwarf' * 4096);
  }","path":"test/release_hygiene_test.dart"}

